contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint64 a) public {
        require(a < 100);
        uint256 beforeBasefee = c.basefee(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(a, a, a, bytes32(0), a, bytes32(0), a, a); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.basefee() == beforeBasefee);
    }
    receive() external payable {}
}

