// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 a) internal {
        a = uint64(bound(uint256(a), 0, 99));
        uint256 beforeBasefee;
        try c.basefee() returns (uint256 __r) { beforeBasefee = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(a, a, a, bytes32(0), a, bytes32(0), a, a) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.basefee() == beforeBasefee);
    }

    function testFuzz_run(uint64 a) public {
        _run(a);
    }

    receive() external payable {}
}
